insert into chart_templates
  (country, code, name, name_i18n, is_default, audience, statements,
   certification_status, legal_reference, source_key)
values
  ('PK', 'default', 'Pakistan reference chart of accounts', '{}'::jsonb, true, 'companies', array['PK-IFRS-IS', 'PK-IFRS-SFP']::text[], null, 'There is no legal chart of accounts in Pakistan. The Companies Act, 2017 requires a company to keep books of account and to prepare financial statements in the formats and with the disclosures of its Schedules; the Third Schedule sets the framework by class of company — full IFRS for listed, public interest and large-sized companies, IFRS for SMEs for medium-sized companies and the Revised Accounting and Financial Reporting Standard for small-sized entities for the others — and the Fourth and Fifth Schedules set the layout and the disclosures. This chart is original: four digits, blocked so that each range reaches one line of the statements below, with the accounts a Pakistani company actually keeps — the federal sales tax and the further tax kept apart from the five sales taxes on services (Punjab, Sindh, Khyber Pakhtunkhwa, Balochistan and the Islamabad Capital Territory), each payable to its own authority, the net federal sales tax due to or from FBR after a return, sales tax owed to Customs on imports, income tax withheld at source, EOBI and provincial social security contributions, the Workers'' Profit Participation Fund and the Workers'' Welfare Fund, Islamic financing and the super tax.', 'companies-act-2017')
on conflict (country, code) do update set
  name                 = excluded.name,
  name_i18n            = excluded.name_i18n,
  is_default           = excluded.is_default,
  audience             = excluded.audience,
  statements           = excluded.statements,
  certification_status = excluded.certification_status,
  legal_reference      = excluded.legal_reference,
  source_key           = excluded.source_key;

