insert into tax_templates
  (country, code, name, name_i18n, description, amount_type, amount, applies_to, treatment,
   valid_from, valid_to, legal_reference, vat_category, exemption_code, sequence,
   tax_kind, recoverable, conditions, jurisdiction, price_include, cash_basis,
   cash_basis_transition_account_code, source_key,
   applies_seller_territory, applies_buyer_territory, applies_supply_territory,
   applies_supply_vs_seller)
values
  ('PK', 'PK-P-10', 'Purchase at a reduced rate of 10 %', '{}'::jsonb, 'A local purchase of a good the Eighth Schedule taxes at 10 %, the tax being adjustable', 'percent', 10, 'purchase', 'domestic', date '2025-07-01', null, 'Sales Tax Act, 1990, Eighth Schedule, Table-1 — the 10 % serials (photovoltaic cells at serial 90, tractors at serial 86, oil cake at serial 85); s. 7(1) for the deduction. STR-7 has no separate row for a reduced-rate purchase: it is reported in row 1.', null, null, 220, 'sales_tax', true, '{}'::tax_condition[], null, false, false, null, 'sta-1990', null, null, null, null),
  ('PK', 'PK-P-17', 'Purchase of goods, former standard rate 17 %', '{}'::jsonb, 'The standard rate before the Finance (Supplementary) Act, 2023, closed on 13 February 2023', 'percent', 17, 'purchase', 'domestic', date '2022-07-01', date '2023-02-13', 'Sales Tax Act, 1990, s. 3(1) before the Finance (Supplementary) Act, 2023, and s. 7(1) for the deduction; FBR Circular No. 01 of 2023.', null, null, 210, 'sales_tax', true, '{}'::tax_condition[], null, false, false, null, 'circular-01-2023', null, null, null, null),
  ('PK', 'PK-P-18', 'Purchase of goods, standard rate 18 %', '{}'::jsonb, 'A local purchase from a registered supplier, the sales tax being adjustable as input tax', 'percent', 18, 'purchase', 'domestic', date '2023-02-14', null, 'Sales Tax Act, 1990, s. 7(1) — a registered person may deduct input tax paid on goods purchased for taxable supplies from the output tax of the period; s. 8 — the cases where no credit is allowed; s. 8B — the 90 % ceiling of input tax on output tax, which the pack does not apply (see the README). Declared on STR-7, row 1 (domestic purchases from registered persons, excluding fixed assets).', null, null, 200, 'sales_tax', true, '{}'::tax_condition[], null, false, false, null, 'sta-1990', null, null, null, null),
  ('PK', 'PK-P-18-CAP', 'Purchase of capital goods, standard rate 18 %', '{}'::jsonb, 'Plant and machinery bought from a registered supplier for taxable supplies, the sales tax being adjustable as input tax', 'percent', 18, 'purchase', 'domestic', date '2023-02-14', null, 'Sales Tax Act, 1990, s. 7(1) and s. 8B(1) second-to-last proviso — the 90 % ceiling on input tax does not apply to fixed assets or capital goods. Declared on STR-7, row 4 (capital goods and fixed assets, domestic purchases and imports). Section 8(1)(i) excludes from adjustment vehicles of Chapter 87, electrical and gas appliances, furniture and furnishings and office equipment: those use PK-P-18-NC.', null, null, 230, 'sales_tax', true, '{}'::tax_condition[], null, false, false, null, 'sta-1990', null, null, null, null),
  ('PK', 'PK-P-18-NC', 'Purchase at 18 %, input tax not allowed', '{}'::jsonb, 'A vehicle, an electrical appliance, furniture or office equipment: the sales tax becomes part of the cost', 'percent', 18, 'purchase', 'domestic', date '2023-02-14', null, 'Sales Tax Act, 1990, s. 8(1)(i) — a registered person may not reclaim or deduct input tax paid on vehicles falling in Chapter 87 of the First Schedule to the Customs Act, 1969, parts of such vehicles, electrical and gas appliances, furniture furnishings and office equipment (excluding electronic cash registers), other than goods acquired for sale or re-sale; s. 8(1)(g) — goods and services acquired for personal or non-business consumption. The tax lands on the account of the line and reaches no box of STR-7. The same code serves a purchase attributable to exempt supplies (s. 8(1)(a)), where the whole input tax is lost.', null, null, 240, 'sales_tax', true, '{}'::tax_condition[], null, false, false, null, 'sta-1990', null, null, null, null),
  ('PK', 'PK-P-BRA-15', 'Purchase of services, Balochistan sales tax on services 15 % (BRA)', '{}'::jsonb, 'A service bought from a provider registered with the Balochistan Revenue Authority, the tax being adjustable against output tax of the same authority', 'percent', 15, 'purchase', 'domestic', date '2015-07-01', null, 'The provincial or territorial statute of the sales tax on services of Balochistan — see PK-S-BRA-15 — lets a registered person adjust the tax paid on services against the tax he collects for the same authority; the input account is kept apart per authority for that reason. Whether the federal tax may adjust it is s. 8(1)(j) of the Sales Tax Act, 1990, which bars input tax on services where the provincial law bars its adjustment. The amount reaches no box of the federal return.', null, null, 330, 'sales_tax', true, '{}'::tax_condition[], null, false, false, null, 'bra-act', null, null, null, null),
  ('PK', 'PK-P-EX', 'Purchase, exempt or not subject', '{}'::jsonb, 'A purchase of an exempt good, or of a service that carries no federal tax', 'percent', 0, 'purchase', 'exempt', date '2022-07-01', null, 'Sales Tax Act, 1990, s. 13(1) and the Sixth Schedule; no tax is charged, so none is adjusted, and STR-7 carries no row for it.', null, null, 260, 'sales_tax', true, '{}'::tax_condition[], null, false, false, null, 'sta-1990', null, null, null, null),
  ('PK', 'PK-P-ICT-15', 'Purchase of services, Islamabad Capital Territory sales tax on services 15 % (ICT)', '{}'::jsonb, 'A service bought from a provider registered with the the Federal Board of Revenue, for the Islamabad Capital Territory, the tax being adjustable against output tax of the same authority', 'percent', 15, 'purchase', 'domestic', date '2022-07-01', null, 'The provincial or territorial statute of the sales tax on services of Islamabad Capital Territory — see PK-S-ICT-15 — lets a registered person adjust the tax paid on services against the tax he collects for the same authority; the input account is kept apart per authority for that reason. Whether the federal tax may adjust it is s. 8(1)(j) of the Sales Tax Act, 1990, which bars input tax on services where the provincial law bars its adjustment. The amount reaches no box of the federal return.', null, null, 340, 'sales_tax', true, '{}'::tax_condition[], null, false, false, null, 'ict-ordinance', null, null, null, null),
  ('PK', 'PK-P-IMP-18', 'Import of goods, standard rate 18 %', '{}'::jsonb, 'Goods imported into Pakistan, the sales tax paid at Customs being adjustable', 'percent', 18, 'purchase', 'import', date '2023-02-14', null, 'Sales Tax Act, 1990, s. 3(1)(b) — sales tax at eighteen per cent of the value of goods imported into Pakistan; s. 6(1) — the tax on imported goods is charged and paid in the same manner and at the same time as a duty of customs; s. 7(1) — the tax paid is adjustable. Declared on STR-7, row 3 (imports, excluding fixed assets) and on Annex-B. The tax is booked to the input account and owed to Customs through account 2125; customs duty and the value addition tax on commercial imports are not modelled.', null, null, 270, 'sales_tax', true, '{}'::tax_condition[], null, false, false, null, 'sta-1990', null, null, null, null),
  ('PK', 'PK-P-KPRA-15', 'Purchase of services, Khyber Pakhtunkhwa sales tax on services 15 % (KPRA)', '{}'::jsonb, 'A service bought from a provider registered with the Khyber Pakhtunkhwa Revenue Authority, the tax being adjustable against output tax of the same authority', 'percent', 15, 'purchase', 'domestic', date '2022-07-01', null, 'The provincial or territorial statute of the sales tax on services of Khyber Pakhtunkhwa — see PK-S-KPRA-15 — lets a registered person adjust the tax paid on services against the tax he collects for the same authority; the input account is kept apart per authority for that reason. Whether the federal tax may adjust it is s. 8(1)(j) of the Sales Tax Act, 1990, which bars input tax on services where the provincial law bars its adjustment. The amount reaches no box of the federal return.', null, null, 320, 'sales_tax', true, '{}'::tax_condition[], null, false, false, null, 'kp-act', null, null, null, null),
  ('PK', 'PK-P-PRA-16', 'Purchase of services, Punjab sales tax on services 16 % (PRA)', '{}'::jsonb, 'A service bought from a provider registered with the Punjab Revenue Authority, the tax being adjustable against output tax of the same authority', 'percent', 16, 'purchase', 'domestic', date '2021-07-01', null, 'The provincial or territorial statute of the sales tax on services of Punjab — see PK-S-PRA-16 — lets a registered person adjust the tax paid on services against the tax he collects for the same authority; the input account is kept apart per authority for that reason. Whether the federal tax may adjust it is s. 8(1)(j) of the Sales Tax Act, 1990, which bars input tax on services where the provincial law bars its adjustment. The amount reaches no box of the federal return.', null, null, 300, 'sales_tax', true, '{}'::tax_condition[], null, false, false, null, 'pra-act', null, null, null, null),
  ('PK', 'PK-P-SRB-15', 'Purchase of services, Sindh sales tax on services 15 % (SRB)', '{}'::jsonb, 'A service bought from a provider registered with the Sindh Revenue Board, the tax being adjustable against output tax of the same authority', 'percent', 15, 'purchase', 'domestic', date '2025-07-01', null, 'The provincial or territorial statute of the sales tax on services of Sindh — see PK-S-SRB-15 — lets a registered person adjust the tax paid on services against the tax he collects for the same authority; the input account is kept apart per authority for that reason. Whether the federal tax may adjust it is s. 8(1)(j) of the Sales Tax Act, 1990, which bars input tax on services where the provincial law bars its adjustment. The amount reaches no box of the federal return.', null, null, 310, 'sales_tax', true, '{}'::tax_condition[], null, false, false, null, 'srb-act', null, null, null, null),
  ('PK', 'PK-P-UNREG', 'Purchase from an unregistered supplier', '{}'::jsonb, 'A purchase from a person with no registration number: no sales tax is charged and none can be adjusted', 'percent', 0, 'purchase', 'domestic', date '2022-07-01', null, 'Sales Tax Act, 1990, s. 3(3) and s. 7(1) — only tax charged by a registered person is adjustable; Sales Tax Rules, 2006, form STR-7, row 2 — domestic purchases from unregistered persons, reported with no sales tax credit. Annex-A carries the supplier''s details.', null, null, 250, 'sales_tax', true, '{}'::tax_condition[], null, false, false, null, 'sta-1990', null, null, null, null),
  ('PK', 'PK-S-1', 'Sale at a reduced rate of 1 % — locally assembled electric vehicles', '{}'::jsonb, 'Locally manufactured or assembled four-wheeled electric vehicles (small cars and SUVs up to 50 kWh, light commercial vehicles up to 150 kWh) supplied locally, until 30 June 2027', 'percent', 1, 'sale', 'domestic', date '2021-07-01', date '2027-06-30', 'Sales Tax Act, 1990, Eighth Schedule, Table-1, serial 71 — locally manufactured or assembled electric vehicles (4 wheelers), small cars and SUVs with a 50 kWh battery or below and light commercial vehicles with a 150 kWh battery or below, at 1 % if supplied locally, till 30 June 2027 (the date substituted by the Finance Act, 2026). Serial 81 puts substances registered as drugs under the Drugs Act, 1976 at 1 % as well, as a final discharge of tax with no input tax adjusted in the supply chain, which this code does not model.', 'S', null, 40, 'sales_tax', true, '{}'::tax_condition[], null, false, false, null, 'sta-1990', null, null, null, null),
  ('PK', 'PK-S-10', 'Sale at a reduced rate of 10 % — photovoltaic cells and panels', '{}'::jsonb, 'Photovoltaic cells, whether or not assembled in modules or made up into panels (heading 8541.4200 and 8541.4300), taxed at 10 % under the Eighth Schedule', 'percent', 10, 'sale', 'domestic', date '2025-07-01', null, 'Sales Tax Act, 1990, s. 3(2)(aa) and the Eighth Schedule, Table-1, serial 90 — photovoltaic cells, whether or not assembled in modules or made up into panels, at 10 %, added by the Finance Act, 2025. A reduced-rate supply is reported on STR-7 in row 10 and is included in row 9. The same rate applies to other serials of the Eighth Schedule (tractors, oil cake, stationery, poultry feed: serials 84 to 88).', 'S', null, 30, 'sales_tax', true, '{}'::tax_condition[], null, false, false, null, 'sta-1990', null, null, null, null),
  ('PK', 'PK-S-17', 'Sale of goods, former standard rate 17 %', '{}'::jsonb, 'The standard rate before the Finance (Supplementary) Act, 2023, closed on 13 February 2023', 'percent', 17, 'sale', 'domestic', date '2022-07-01', date '2023-02-13', 'Sales Tax Act, 1990, s. 3(1), before the substitution of eighteen for seventeen by the Finance (Supplementary) Act, 2023 (footnote 142 to the Act as updated to 30 June 2026); FBR Circular No. 01 of 2023 — the standard rate has been increased from 17% to 18%. The change was first applied from 14 February 2023 by notification; the day is the one the notification gives, and a supply invoiced across it is the accountant''s to settle. The code is kept, closed, so that books of the earlier months still resolve; it does not claim to cover the periods before 1 July 2022.', 'S', null, 50, 'sales_tax', true, '{}'::tax_condition[], null, false, false, null, 'circular-01-2023', null, null, null, null),
  ('PK', 'PK-S-18', 'Sale of goods, standard rate 18 %', '{}'::jsonb, 'A taxable supply of goods by a registered person to a registered buyer, charged at the standard rate of section 3(1)', 'percent', 18, 'sale', 'domestic', date '2023-02-14', null, 'Sales Tax Act, 1990, s. 3(1) — sales tax is charged at the rate of eighteen per cent of the value of taxable supplies made by a registered person in the course or furtherance of a taxable activity, the figure the Finance (Supplementary) Act, 2023 substituted for seventeen (footnote to s. 3(1) of the Act as updated to 30 June 2026); FBR Circular No. 01 of 2023 — the standard rate has been increased from 17% to 18%. Declared on STR-7, row 9 (local supplies) of the Sales Tax Rules, 2006: the taxable value and the sales tax of the month.', 'S', null, 10, 'sales_tax', true, '{}'::tax_condition[], null, false, false, null, 'sta-1990', null, null, null, null),
  ('PK', 'PK-S-18-FT', 'Sale of goods to an unregistered buyer, 18 % + further tax 4 %', '{}'::jsonb, 'A taxable supply to a buyer who has no registration number or is not an active taxpayer: the 18 % of section 3(1) plus the 4 % further tax of section 3(1A), both on the same value', 'percent', 22, 'sale', 'domestic', date '2023-07-01', null, 'Sales Tax Act, 1990, s. 3(1A) — where taxable supplies are made to a person who has not obtained a registration number or is not an active taxpayer, a further tax at the rate of four per cent of the value is charged, levied and paid in addition to the rate of section 3(1); the Finance Act, 2023 substituted four for three (footnote 148 to the Act as updated to 30 June 2026). The two taxes are side by side on one value, so the line carries 22 % and splits it 81.818 / 18.182 between the sales tax (STR-7 row 9) and the further tax (STR-7 row 23a). The Federal Government may exempt classes of supplies from the further tax by notification; none is modelled. The factors are the closest values the three decimals of the posting factor allow: on a value above about 12,500 rupees the split can differ by a paisa from 18 % and 4 % computed separately.', 'S', null, 20, 'sales_tax', true, '{}'::tax_condition[], null, false, false, null, 'sta-1990', null, null, null, null),
  ('PK', 'PK-S-BRA-15', 'Sale of services, Balochistan sales tax on services 15 % (BRA)', '{}'::jsonb, 'A taxable service provided in Balochistan, charged at the standard rate of the Balochistan Revenue Authority and declared to that authority and not on the federal return', 'percent', 15, 'sale', 'domestic', date '2015-07-01', null, 'Balochistan Sales Tax on Services Act, 2015, in force from 1 July 2015 (section 1(3)); the Second Schedule taxes the listed services (hotels, restaurants, marriage halls, clubs, caterers, advertisement and others) at 15 %; section 2(18) — the due date is the 15th day of the month following the tax period unless the Authority notifies another. The text read is the version published by the Provincial Assembly Secretariat; the Authority''s consolidated Act, amended by the Balochistan Finance Act, 2024, is the one to confirm. The tax is posted to its own account and reaches no box of the federal return (STR-7); it is declared and paid to its own authority on that authority''s portal.', 'S', null, 130, 'sales_tax', true, '{}'::tax_condition[], null, false, false, null, 'bra-act', null, null, null, null),
  ('PK', 'PK-S-EX', 'Exempt supply — Sixth Schedule', '{}'::jsonb, 'A supply the Sixth Schedule exempts from sales tax, such as pulses', 'percent', 0, 'sale', 'exempt', date '2022-07-01', null, 'Sales Tax Act, 1990, s. 13(1) and the Sixth Schedule, Table-1, serial 14 — pulses (heading 0713) among the supplies and imports exempt from the tax; s. 8(1)(a) — input tax on goods used for any purpose other than taxable supplies is not reclaimable, and s. 8(2) allows the proportion attributable to taxable supplies where both are made. STR-7 has no row for exempt supplies: they are reported in Annex-C and reach no box of this pack.', 'E', null, 80, 'sales_tax', true, '{}'::tax_condition[], null, false, false, null, 'sta-1990', null, null, null, null),
  ('PK', 'PK-S-ICT-15', 'Sale of services, Islamabad Capital Territory sales tax on services 15 % (ICT)', '{}'::jsonb, 'A taxable service provided in Islamabad Capital Territory, charged at the standard rate of the the Federal Board of Revenue, for the Islamabad Capital Territory and declared to that authority and not on the federal return', 'percent', 15, 'sale', 'domestic', date '2022-07-01', null, 'Islamabad Capital Territory (Tax on Services) Ordinance, 2001, section 3 and the Schedule — services are taxed at the rate in column (4) of Table-1, which the Finance Act, 2022 fixed at fifteen percent (the words "sixteen percent" and "seventeen percent" were substituted, footnote 13 of the Ordinance as updated to 30 June 2025). The Ordinance is administered by the Federal Board of Revenue and its tax is declared apart from the federal sales tax on goods. The text consulted is the 2025 edition; whether the Finance Act, 2026 moved the rate was not established. The tax is posted to its own account and reaches no box of the federal return (STR-7); it is declared and paid to its own authority on that authority''s portal.', 'S', null, 140, 'sales_tax', true, '{}'::tax_condition[], null, false, false, null, 'ict-ordinance', null, null, null, null),
  ('PK', 'PK-S-KPRA-15', 'Sale of services, Khyber Pakhtunkhwa sales tax on services 15 % (KPRA)', '{}'::jsonb, 'A taxable service provided in Khyber Pakhtunkhwa, charged at the standard rate of the Khyber Pakhtunkhwa Revenue Authority and declared to that authority and not on the federal return', 'percent', 15, 'sale', 'domestic', date '2022-07-01', null, 'Khyber Pakhtunkhwa Sales Tax on Services Act, 2022 (Act XIX of 2022), section 9(1) proviso — fifteen percent is the standard or general rate of tax for all purposes of the Act, the Second Schedule specifying the rates of particular services; section 2(x) — the due date of payment is the 15th day of the month following the tax period and the due date of the return is the 18th. The Act came into force at once, with dates per service set by notification; 1 July 2022 is used as the start of the code. The tax is posted to its own account and reaches no box of the federal return (STR-7); it is declared and paid to its own authority on that authority''s portal.', 'S', null, 120, 'sales_tax', true, '{}'::tax_condition[], null, false, false, null, 'kp-act', null, null, null, null),
  ('PK', 'PK-S-NS', 'Supply outside the federal sales tax — not subject', '{}'::jsonb, 'A supply that the Sales Tax Act does not tax: a service (a provincial or territorial tax applies instead, or none), or goods outside the taxable activity', 'percent', 0, 'sale', 'not_subject', date '2022-07-01', null, 'Sales Tax Act, 1990, s. 3(1)(a) — the federal tax is charged on taxable supplies of goods made by a registered person in the course of a taxable activity; the taxation of services belongs to the provinces and to the Islamabad Capital Territory, whose tax codes are PK-S-PRA-16, PK-S-SRB-15, PK-S-KPRA-15, PK-S-BRA-15 and PK-S-ICT-15. A service supplied where no provincial law taxes it, or one that law exempts or zero-rates for export, uses this code; that treatment is set by each provincial statute and is not modelled here.', 'O', null, 90, 'sales_tax', true, '{}'::tax_condition[], null, false, false, null, 'sta-1990', null, null, null, null),
  ('PK', 'PK-S-PRA-16', 'Sale of services, Punjab sales tax on services 16 % (PRA)', '{}'::jsonb, 'A taxable service provided in Punjab, charged at the standard rate of the Punjab Revenue Authority and declared to that authority and not on the federal return', 'percent', 16, 'sale', 'domestic', date '2021-07-01', null, 'Punjab Sales Tax on Services Act, 2012, section 2(41A) — "Standard Rate" means sixteen percent (inserted by the Punjab Finance Act, 2021), and the general entry of the Second Schedule taxes all services not otherwise specified at that rate; section 10A lets a provider charge the standard rate in place of a reduced one with the Authority''s permission. The Punjab Laws portal and the Punjab Revenue Authority site refused the connection from the place this pack was written, so the Act itself was not opened: the rate and the 2021 insertion are those the consolidated text of the portal states in the extract a search of that portal returned, and are to be confirmed against the Act as amended by the Punjab Finance Act, 2026. The tax is posted to its own account and reaches no box of the federal return (STR-7); it is declared and paid to its own authority on that authority''s portal.', 'S', null, 100, 'sales_tax', true, '{}'::tax_condition[], null, false, false, null, 'pra-act', null, null, null, null),
  ('PK', 'PK-S-SRB-15', 'Sale of services, Sindh sales tax on services 15 % (SRB)', '{}'::jsonb, 'A taxable service provided in Sindh, charged at the standard rate of the Sindh Revenue Board and declared to that authority and not on the federal return', 'percent', 15, 'sale', 'domestic', date '2025-07-01', null, 'Sindh Sales Tax on Services Act, 2011, section 8(1) as substituted by the Sindh Finance Act, 2025 (assented to on 30 June 2025) — tax is charged on the value of a taxable service at the rate of fifteen per cent, which is the standard rate, and the services listed in the Second Schedule bear the rate that Schedule specifies; section 2(36) — the due date is the 15th day of the month following the tax period unless the Board notifies another. The tax is posted to its own account and reaches no box of the federal return (STR-7); it is declared and paid to its own authority on that authority''s portal.', 'S', null, 110, 'sales_tax', true, '{}'::tax_condition[], null, false, false, null, 'srb-act', null, null, null, null),
  ('PK', 'PK-S-ZR-DOM', 'Domestic supply, zero-rated — Fifth Schedule', '{}'::jsonb, 'A local supply the Fifth Schedule zero-rates, such as a supply to a diplomatic mission or a privileged organisation', 'percent', 0, 'sale', 'domestic', date '2022-07-01', null, 'Sales Tax Act, 1990, s. 4(a) and the Fifth Schedule, serial 2 — supply to diplomats, diplomatic missions, privileged persons and privileged organizations covered by the Acts, Orders, Rules, Regulations and Agreements the Schedule names; serial 5 — raw materials, components and goods for further manufacture in the Export Processing Zones; serial 7 — supplies to exporters under the Duty and Tax Remission Rules, 2001. The STR-7 form of the Sales Tax Rules, 2006 has no separate row for a local zero-rated supply; the pack reports it in row 9 at nil tax, which is the reading to confirm with a local accountant.', 'Z', null, 70, 'sales_tax', true, '{}'::tax_condition[], null, false, false, null, 'sta-1990', null, null, null, null),
  ('PK', 'PK-S-ZR-EXP', 'Export of goods, zero-rated', '{}'::jsonb, 'Goods exported, charged at zero per cent', 'percent', 0, 'sale', 'export', date '2022-07-01', null, 'Sales Tax Act, 1990, s. 4(a) — goods exported, or the goods specified in the Fifth Schedule, are charged to tax at the rate of zero per cent, notwithstanding section 3 (the further tax of section 3(1A) is expressly not displaced, and no unregistered buyer arises on an export). Declared on STR-7, row 11 (exports).', 'G', null, 60, 'sales_tax', true, '{}'::tax_condition[], null, false, false, null, 'sta-1990', null, null, null, null)
