insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('PK', 'PK-STR7', 'Monthly Sales Tax Return (form STR-7, filed on FBR IRIS)', array['month']::declaration_period[], 'month'::declaration_period, date '2023-02-14', null, 'Sales Tax Act, 1990, s. 26(1) — every registered person furnishes, not later than the due date, a true, complete and correct return in the prescribed form, indicating the purchases and the supplies made during a tax period, the tax due and paid and such other information as is prescribed; s. 2(43) — a tax period is one month unless the Board notifies another (the quarterly return of s. 26(1) first proviso is notified for some classes, such as brick kilns and CNG dealers, and is not modelled). The prescribed form is STR-7, Sales Tax and Federal Excise Return, of the Sales Tax Rules, 2006 (rule 14(1)), filed electronically under rule 18 on FBR IRIS with Annex-A (purchases), Annex-C (sales) and Annex-I (debit and credit notes). The pack carries the rows 1 to 5, 8, 9, 10, 11, 15, 17, 23a, 30 and 32 of the form, each with the adaptation said on its box; the federal excise duty, petroleum levy, withholding and sector rows are outside it. The sales taxes on services of the four provinces and the Islamabad Capital Territory are never on this form: each is declared to its own authority.', true,'day_of_month_after_period'::filing_deadline_rule, 18, null, 'Sales Tax Act, 1990, s. 2(9) — the due date of a return is the 15th day of the month following the tax period, or such other date as the Board specifies, and different dates may be specified for different parts or annexures of the return; Sales Tax Rules, 2006, rule 18(9) — where the due date is the 15th, the tax due is deposited by the 15th and the return is submitted electronically by the 18th of the same month. The pack keeps the 18th: it is the day by which the return, which is what this report is, is filed; the payment is due three days earlier, on the 15th, and an ordinary taxpayer who files on the 18th has already paid. Electricity distribution companies, independent power producers, gas companies, petroleum exploration companies, CNG dealers and brick kilns have the later dates of the table to rule 18(9). A date that falls on a public holiday is not moved by the rule.', 'str-2006', null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
  file_format         = excluded.file_format;

insert into tax_report_box_templates
  (country, report_code, box, kind, name, name_i18n, sequence, print_sequence,
   plus_boxes, minus_boxes, rate, rate_of_box, floor_zero, hidden, xml_element,
   legal_reference, source_key)
values
  ('PK', 'PK-STR7', '1', 'base', 'Domestic purchases from registered persons — taxable value', '{}'::jsonb, 10, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Sales Tax Rules, 2006, form STR-7 (rule 14(1)), row 1 — domestic purchases from registered persons, excluding fixed assets, reported with Annex-A and Annex-I; the pack carries the taxable value and the sales tax (the gross value column is not kept).', 'str-2006'),
  ('PK', 'PK-STR7', '1T', 'tax', 'Domestic purchases from registered persons — sales tax', '{}'::jsonb, 20, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Sales Tax Rules, 2006, form STR-7 (rule 14(1)), row 1 — the sales tax credit of the same purchases, Sales Tax Act, 1990, s. 7(1).', 'str-2006'),
  ('PK', 'PK-STR7', '2', 'base', 'Domestic purchases from unregistered persons — taxable value', '{}'::jsonb, 30, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Sales Tax Rules, 2006, form STR-7 (rule 14(1)), row 2 — domestic purchases from unregistered persons, which carry no sales tax credit.', 'str-2006'),
  ('PK', 'PK-STR7', '3', 'base', 'Imports excluding fixed assets — taxable value', '{}'::jsonb, 40, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Sales Tax Rules, 2006, form STR-7 (rule 14(1)), row 3 — imports excluding fixed assets, reported with Annex-B (the value addition tax on commercial imports is not modelled).', 'str-2006'),
  ('PK', 'PK-STR7', '3T', 'tax', 'Imports excluding fixed assets — sales tax', '{}'::jsonb, 50, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Sales Tax Rules, 2006, form STR-7 (rule 14(1)), row 3 — the sales tax paid at Customs on those imports, s. 3(1)(b) and s. 7(1).', 'str-2006'),
  ('PK', 'PK-STR7', '4', 'base', 'Capital goods and fixed assets — taxable value', '{}'::jsonb, 60, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Sales Tax Rules, 2006, form STR-7 (rule 14(1)), row 4 — capital goods and fixed assets, domestic purchases and imports, reported with Annex-A, Annex-I and Annex-B. The pack posts domestic purchases to this row; an imported capital good is posted by the import code to row 3.', 'str-2006'),
  ('PK', 'PK-STR7', '4T', 'tax', 'Capital goods and fixed assets — sales tax', '{}'::jsonb, 70, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Sales Tax Rules, 2006, form STR-7 (rule 14(1)), row 4 — the sales tax credit of those purchases.', 'str-2006'),
  ('PK', 'PK-STR7', '5', 'total', 'Input for the month', '{}'::jsonb, 80, null, array['1T', '3T', '4T']::text[], '{}'::text[], null, null, false, false, null, 'Sales Tax Rules, 2006, form STR-7 (rule 14(1)), row 5 — input for the month = (1 + 3 + 4), the sales tax columns.', 'str-2006'),
  ('PK', 'PK-STR7', '8', 'total', 'Accumulated credit', '{}'::jsonb, 90, null, array['5']::text[], '{}'::text[], null, null, false, false, null, 'Sales Tax Rules, 2006, form STR-7 (rule 14(1)), row 8 — accumulated credit = 5 + 6 + 7b + 6c − (6a + 6b + 7 + 7a). The pack carries row 5 alone: the credit brought forward (row 6), the inadmissible input tax (rows 6a, 6b, 7, 7a) and the allowance of earlier disallowed credit (rows 7b, 6c) are not modelled, so the credit the form prints can be lower.', 'str-2006'),
  ('PK', 'PK-STR7', '9A', 'base', 'Local supplies at the standard rate — taxable value', '{}'::jsonb, 100, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Sales Tax Rules, 2006, form STR-7 (rule 14(1)), row 9 — total goods or services supplied locally; the pack splits the row into the supplies at the standard rate (this box) and those at reduced rates (row 10), and adds them in row 9. A local zero-rated supply is carried here at nil tax.', 'str-2006'),
  ('PK', 'PK-STR7', '9AT', 'tax', 'Local supplies at the standard rate — sales tax', '{}'::jsonb, 110, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Sales Tax Rules, 2006, form STR-7 (rule 14(1)), row 9 — the sales tax of the supplies at the standard rate, Sales Tax Act, 1990, s. 3(1).', 'str-2006'),
  ('PK', 'PK-STR7', '10', 'base', 'Local supplies at reduced rates — taxable value', '{}'::jsonb, 120, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Sales Tax Rules, 2006, form STR-7 (rule 14(1)), row 10 — goods or services supplied locally at reduced rates (Eighth Schedule), reported with Annex-C and Annex-I. They are also included in row 9.', 'str-2006'),
  ('PK', 'PK-STR7', '10T', 'tax', 'Local supplies at reduced rates — sales tax', '{}'::jsonb, 130, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Sales Tax Rules, 2006, form STR-7 (rule 14(1)), row 10 — the sales tax of those supplies.', 'str-2006'),
  ('PK', 'PK-STR7', '9', 'total', 'Total local supplies, including reduced-rate sales — taxable value', '{}'::jsonb, 140, null, array['9A', '10']::text[], '{}'::text[], null, null, false, false, null, 'Sales Tax Rules, 2006, form STR-7 (rule 14(1)), row 9 — total goods or services supplied locally, including reduced-rate sales, taxable value.', 'str-2006'),
  ('PK', 'PK-STR7', '9T', 'total', 'Total local supplies, including reduced-rate sales — sales tax', '{}'::jsonb, 150, null, array['9AT', '10T']::text[], '{}'::text[], null, null, false, false, null, 'Sales Tax Rules, 2006, form STR-7 (rule 14(1)), row 9 — total goods or services supplied locally, including reduced-rate sales, sales tax.', 'str-2006'),
  ('PK', 'PK-STR7', '11', 'base', 'Exports — taxable value', '{}'::jsonb, 160, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Sales Tax Rules, 2006, form STR-7 (rule 14(1)), row 11 — exports, charged at zero per cent, Sales Tax Act, 1990, s. 4(a).', 'str-2006'),
  ('PK', 'PK-STR7', '15', 'total', 'Output tax', '{}'::jsonb, 170, null, array['9T']::text[], '{}'::text[], null, null, false, false, null, 'Sales Tax Rules, 2006, form STR-7 (rule 14(1)), row 15 — output tax = (9 + 14a + 19 + 20). The pack carries row 9 alone: the CNG sector, the steel sector and the ship-breaking adjustments are not modelled.', 'str-2006'),
  ('PK', 'PK-STR7', '17', 'total', 'Accumulated debit', '{}'::jsonb, 180, null, array['15']::text[], '{}'::text[], null, null, false, false, null, 'Sales Tax Rules, 2006, form STR-7 (rule 14(1)), row 17 — accumulated debit = (15 − 16). The sales tax deducted by withholding agents (row 16, Eleventh Schedule) is not modelled, so the debit the form prints can be lower.', 'str-2006'),
  ('PK', 'PK-STR7', '23a', 'tax', 'Further tax on supplies to unregistered persons', '{}'::jsonb, 190, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Sales Tax Rules, 2006, form STR-7 (rule 14(1)), row 23a — further tax charged on supplies made to an unregistered person, Annex-C; Sales Tax Act, 1990, s. 3(1A).', 'sta-1990'),
  ('PK', 'PK-STR7', '32A', 'total', 'Sales tax payable before the further tax and the ceiling on credit', '{}'::jsonb, 200, null, array['17']::text[], array['8']::text[], null, null, true, true, null, 'Sales Tax Rules, 2006, form STR-7 (rule 14(1)), row 32 — sales tax payable = [if 17 > 25 then (17 − 25)] + [12 + 14b + 18 + 21 + 22 + 23 + 23a + 23b]. This box is the first term with row 25 replaced by row 8: the ceiling of Sales Tax Act, 1990, s. 8B(1) (input tax not above ninety per cent of the output tax, with the exclusions rows 24 to 26 apply) is not applied, because the form states it with a least-of and a conditional that a box cannot express. A registered person subject to s. 8B owes more than this box says.', 'str-2006'),
  ('PK', 'PK-STR7', '32', 'total', 'Sales tax payable', '{}'::jsonb, 210, null, array['32A', '23a']::text[], '{}'::text[], null, null, false, false, null, 'Sales Tax Rules, 2006, form STR-7 (rule 14(1)), row 32 — sales tax payable, the net of output tax over input tax with the further tax of row 23a added.', 'str-2006'),
  ('PK', 'PK-STR7', '30', 'total', 'Credit to be carried forward', '{}'::jsonb, 220, null, array['8']::text[], array['17']::text[], null, null, true, false, null, 'Sales Tax Rules, 2006, form STR-7 (rule 14(1)), row 30 — credit to be carried forward, the excess of the credit over the debit when no refund is claimed (rows 28 to 30; the refund claim of row 29 is not modelled).', 'str-2006')
