insert into statement_templates
  (code, country, chart_code, name, kind, framework, valid_from, valid_to, legal_reference,
   source_key)
values
  ('PK-IFRS-IS', 'PK', 'default', 'Statement of profit or loss', 'income_statement', 'IFRS-SME', date '2017-05-30', null, 'Companies Act, 2017, s. 223 and the Fourth Schedule — the statement of profit or loss, with expenses classified by nature as IAS 1 permits; the lines below are the minimum line items of IAS 1 and of section 5 of the IFRS for SMEs. The Workers'' Profit Participation Fund and the Workers'' Welfare Fund are charged above the profit before tax, among the other operating expenses, and the super tax is part of the income tax charge. Other comprehensive income is not carried.', 'companies-act-2017'),
  ('PK-IFRS-SFP', 'PK', 'default', 'Statement of financial position', 'balance_sheet', 'IFRS-SME', date '2017-05-30', null, 'Companies Act, 2017, s. 223 — the financial statements of a company comprise a statement of financial position, a statement of profit or loss and other comprehensive income, a statement of changes in equity and a statement of cash flows with the notes, prepared in the form and with the disclosures of the Fourth and Fifth Schedules and under the framework the Third Schedule assigns to its class; the lines below are the minimum line items of IAS 1 and of section 4 of the IFRS for SMEs, which a full-IFRS company expands and a small-sized entity under the Revised AFRS condenses. The Schedules'' detailed disclosure formats, and the statements of cash flows and of changes in equity, are not carried.', 'companies-act-2017')
on conflict (code) do update set
