update country_defaults set
  numbering_gapless             = false,
  number_format                 = '{CODE}-{YYYY}-{NNNN}',
  legal_payment_days            = null,
  late_payment_reference        = null,
  numbering_legal_reference     = 'Sales Tax Act, 1990, s. 23(1) — a registered person making a taxable supply issues a serially numbered tax invoice at the time of supply, in Urdu or English, with the particulars of paragraphs (a) to (g), and, from the time the Board notifies, a verifiable and unique FBR invoice number; s. 23(1) second proviso — not more than one tax invoice is issued for a taxable supply. The Act asks for a serial number and does not forbid a gap, which is why the style is `sequential`. The FBR invoice number is issued by the integrated system and is not produced by the numbering of the books.',
  numbering_source_key          = 'sta-1990',
  payment_terms_legal_reference = null,
  payment_terms_source_key      = null,
  tax_point_rule                = 'delivery_date',
  tax_point_legal_reference     = 'Sales Tax Act, 1990, s. 23(1) — the tax invoice is issued at the time of supply of the goods, and s. 6(2) has the tax in respect of taxable supplies made during a tax period paid by the registered person by the prescribed date. The Act as updated to 30 June 2026 contains no stand-alone time-of-supply rule of the kind a value added tax statute carries; `delivery_date` is the reading that follows the invoice being due at the time of supply, and is the point to confirm with a local accountant.',
  tax_point_source_key          = 'sta-1990',
  posted_edit_policy            = null,
  posted_edit_policy_legal_reference = null,
  posted_edit_policy_source_key = null,
  einvoice_profile              = null,
  einvoice_mandatory_from       = null,
  einvoice_obligation           = 'none',
  einvoice_legal_reference      = 'No Pakistani statute obliges a business to exchange a structured electronic invoice with another business in the sense Ekwo''s vocabulary gives the word — there is no Peppol authority, no published profile and no ISO 6523 scheme a party is addressed by, so `profile`, `party_scheme` and `vat_scheme` are null and `obligation` is `none`. What Pakistan has instead is real-time reporting of every invoice to the Federal Board of Revenue, a clearance-style regime outside that vocabulary: Sales Tax Act, 1990, s. 23(1) — the invoice carries a verifiable and unique FBR invoice number from the time the Board notifies; s. 23(3) — a registered person issues electronic invoices subject to the conditions the Board specifies; s. 23(5) — the Board may by notification require any person or class of persons to integrate their electronic invoicing system with the Board''s computerized system for real-time reporting of sales, from the date specified; s. 23(6) — a licensed integrator (PRAL being one) integrates the system, and all Tier-1 retailers integrate their outlets with the Board''s system for real-time reporting of sales; Sales Tax Rules, 2006, Chapter XIV (rules 150Q onwards) — the integrated person supplies only through integrated outlets or invoicing machines, and Annexure-C of the return is auto-filled from the electronic invoices; s. 21(2), as amended by the Finance Act, 2026 — non-compliance with sub-sections (5) and (6) of section 23 or section 40C is a ground for the Commissioner to suspend or blacklist a registration, and invoices of a suspended person are not entertained for refund or input tax credit (s. 21(3)). The notified population and the dates are set by S.R.O. notifications that the pack does not carry and that the Board has revised several times; the pack does not generate the FBR invoice number, call the integration interface or produce a QR code.',
  einvoice_source_key           = 'sta-1990',
  party_scheme                  = null,
  vat_scheme                    = null,
  bank_statement_formats        = null,
  payment_formats               = null,
  fiscal_year_default           = 'calendar'
 where country = 'PK';
